#[local] Abbreviation ASEGS := Asan.M.loaded_segments.
#[local] Abbreviation cellA := (cell Asan.M.loaded_segments).
#[local] Abbreviation wrA := (wr Asan.M.loaded_segments).
#[local] Notation "'U' r" := (bv_unsigned r) (at level 10, r at level 9).

Lemma art_land15_mod16 : forall n, 0 <= n -> n mod 16 = 0 -> Z.land n 15 = 0.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S50!1,5|40;|10;|20;!1,52!1+B+0$n;R+0$Hn;R!2'1,2#1$H;R!3+3+0!2'4#20,2!6'6+0!2'4#3!2'7!1,513$z;R+0!3+3+0#1,2#1!2'8#3!1'93!3':#33&__sat0;R!3';#30#2%~R!2'1,20!2'1,2!2'4#40&__arith;R&__wit;R!1,<+=!1+>+=&__varmap;R!1,?+0!1+@+0&__ff;R!7,A4'C+D+D,E!4,F+0!2,G+0,2,H!2,G+03,I!2'J4,E!4'K#1#3vv!2,L+M,N!3+3+M!2'O#1#3,N!3'P+0,2#2!2'1,23#1").
